window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[17]={"id":"017","numero":17,"titre":"Télémédecine, télésanté et téléservices en santé","objectifs":[{"id":"17-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la télésanté, de la santé digitale et des services supports de santé numérique","contenu":"<p>La <strong><span class=\"kw-def\">télésanté</span></strong> est le concept générique qui englobe l'ensemble des activités de santé réalisées à distance grâce aux <strong><span class=\"kw-def\">technologies de l'information et de la communication (TIC)</span></strong>. Elle se décompose en deux versants : <strong><span class=\"kw-def\">télésanté = télémédecine + télésoin</span></strong>, tous deux définis dans le Code de la santé publique par la <strong><span class=\"kw-def\">loi HPST</span></strong> de <span class=\"kw-chiffre\">2009</span>.</p>\n\n<h4 class=\"kw-def\">Télémédecine = pratique médicale à distance</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Pratique médicale à distance</span></strong> utilisant les <span class=\"kw-def\">TIC</span>, réservée aux <strong>professionnels médicaux</strong> : <span class=\"kw-clinique\">médecin</span>, <span class=\"kw-clinique\">sage-femme</span>, <span class=\"kw-clinique\">chirurgien-dentiste</span>.</li>\n  <li>Met en rapport, entre eux ou avec un patient, un ou plusieurs professionnels de santé.</li>\n  <li>Permet d'<span class=\"kw-def\">établir un diagnostic</span>, d'<span class=\"kw-def\">assurer un suivi</span> (préventif ou post-thérapeutique), de <span class=\"kw-def\">requérir un avis spécialisé</span>, de <span class=\"kw-def\">préparer une décision thérapeutique</span>, de <span class=\"kw-def\">prescrire</span> ou de <span class=\"kw-def\">surveiller</span> l'état du patient.</li>\n  <li>Comprend <strong><span class=\"kw-chiffre\">5 actes</span></strong> remboursés dans le cadre conventionnel (négociation Assurance maladie / professionnels de santé).</li>\n</ul>\n\n<h4 class=\"kw-def\">Télésoin = pratique de soin à distance</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Activités de soin à distance</span></strong> utilisant les <span class=\"kw-def\">TIC</span>, réservées aux <strong>professionnels non médicaux</strong> : <span class=\"kw-clinique\">pharmacien</span>, <span class=\"kw-clinique\">auxiliaires médicaux</span> (infirmier, kinésithérapeute…).</li>\n  <li>Mise en œuvre sur <strong><span class=\"kw-def\">décision partagée</span></strong> patient / professionnel réalisant le télésoin.</li>\n  <li>Périmètre et tarifs négociés entre les professionnels et l'<span class=\"kw-def\">Assurance maladie</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Les 5 actes de télémédecine</h4>\n<table >\n  <thead><tr><th>Acte</th><th>Définition</th><th>Acteurs / modalités</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong><span class=\"kw-def\">Téléconsultation</span></strong></td>\n      <td>Consultation médicale à distance.</td>\n      <td>Patient ↔ médecin ; peut être <strong>assistée</strong> par un <span class=\"kw-clinique\">infirmier</span>, un <span class=\"kw-clinique\">pharmacien</span> ou un <span class=\"kw-clinique\">psychologue</span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Téléexpertise</span></strong></td>\n      <td>Sollicitation à distance de l'avis d'un ou plusieurs confrères.</td>\n      <td>Professionnel médical → confrère(s) ; partage de données (<span class=\"kw-imagerie\">imagerie</span>, <span class=\"kw-bio\">biologie</span>).</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Télésurveillance</span></strong></td>\n      <td>Interprétation à distance de données recueillies sur le lieu de vie.</td>\n      <td>Via un <span class=\"kw-def\">dispositif médical numérique</span> ; suivi des <span class=\"kw-etio\">pathologies chroniques</span>.</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Téléassistance</span></strong></td>\n      <td>Assistance à distance d'un confrère réalisant un acte de soin.</td>\n      <td>Médecin expert → médecin opérateur (ex. thrombolyse).</td>\n    </tr>\n    <tr>\n      <td><strong><span class=\"kw-def\">Régulation médicale</span></strong></td>\n      <td>Réponse médicale téléphonique et orientation dans le parcours de soins.</td>\n      <td>Réalisée par les <strong><span class=\"kw-def\">SAMU – Centre 15</span></strong>.</td>\n    </tr>\n  </tbody>\n</table>\n\n<h4 class=\"kw-def\">Santé numérique : les services socles supports</h4>\n<p>La <strong><span class=\"kw-def\">santé digitale</span></strong> (numérique en santé) regroupe les <strong><span class=\"kw-def\">services socles</span></strong> qui supportent la télésanté :</p>\n<ul>\n  <li><strong><span class=\"kw-def\">MSSanté</span></strong> : messagerie sécurisée de santé (échange entre professionnels).</li>\n  <li><strong><span class=\"kw-def\">DMP</span></strong> : dossier médical partagé (carnet de santé numérique).</li>\n  <li><strong><span class=\"kw-def\">Agenda</span></strong> : centralisation des rendez-vous du patient.</li>\n  <li><strong><span class=\"kw-def\">E-prescription</span></strong> : dématérialisation des ordonnances.</li>\n  <li><strong><span class=\"kw-def\">Outils de coordination</span></strong> du parcours de santé.</li>\n</ul>\n\n<div class=\"callout callout-warn\">⚠️ <strong>Piège :</strong> ne pas confondre la <span class=\"kw-def\">téléassistance</span> (acte médical entre confrères) avec la <span class=\"kw-alerte\">téléalarme / téléassistance domiciliaire</span>, qui permet seulement à une personne de donner l'alerte en cas de problème.</div>","frequence":2},{"id":"17-2","rang":"A","rubrique":"Définition","titre":"Connaître l’intérêt de la télésanté dans les pratiques professionnelles","contenu":"<p>L'intérêt de la <strong><span class=\"kw-def\">télésanté</span></strong> dans les pratiques professionnelles se résume en <strong><span class=\"kw-chiffre\">3 objectifs</span></strong> majeurs : réduire les inégalités d'accès, renforcer la qualité des soins et améliorer leur continuité.</p>\n\n<h4 class=\"kw-def\">1. Diminuer les inégalités d'accès aux soins</h4>\n<ul>\n  <li>Déploiement dans les <strong><span class=\"kw-etio\">territoires à faible densité médicale</span></strong> (zones sous-dotées, déserts médicaux).</li>\n  <li><strong><span class=\"kw-def\">Téléconsultation assistée</span></strong> : renfort du maillage territorial (pharmacie, infirmier).</li>\n  <li><strong><span class=\"kw-def\">Exceptions au parcours de soins</span></strong> autorisées : <span class=\"kw-etio\">absence de médecin traitant</span> + <span class=\"kw-etio\">faible densité médicale</span>.</li>\n  <li>Cadre : <strong><span class=\"kw-def\">loi du 4 mars 2002</span></strong> relative aux droits des malades (inégalités en santé).</li>\n</ul>\n\n<h4 class=\"kw-def\">2. Renforcer l'accès à des soins de qualité</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Téléexpertise</span></strong> : accès à un <span class=\"kw-clinique\">avis spécialisé</span> à distance.</li>\n  <li>Possibilité d'un <span class=\"kw-def\">second avis</span> spécialisé.</li>\n</ul>\n\n<h4 class=\"kw-def\">3. Améliorer la continuité des soins</h4>\n<ul>\n  <li>Suivi à distance des <strong><span class=\"kw-etio\">pathologies chroniques</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Télésurveillance</span></strong> : <span class=\"kw-etio\">insuffisance cardiaque</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">insuffisance rénale chronique</span>, <span class=\"kw-etio\">HTA</span>.</li>\n  <li>Suivi <span class=\"kw-def\">post-hospitalisation</span> (continuité ville-hôpital).</li>\n</ul>\n\n<h4 class=\"kw-def\">Exemples d'organisation en pratique</h4>\n<table >\n  <thead><tr><th>Domaine</th><th>Organisation</th><th>Actes concernés</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Télépathologie</span></strong></td><td>Lames virtuelles en réseau validées par les anatomopathologistes.</td><td>Télédiagnostic ; téléexpertise.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Téléradiologie</span></strong></td><td>Télétransmission d'<span class=\"kw-imagerie\">images</span> et téléinterprétation (demandeur ↔ radiologue).</td><td>Télédiagnostic ; téléexpertise.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">AVC</span></strong></td><td>Connexion urgences périphériques ↔ <span class=\"kw-def\">UNV</span> ; garde de neurologie mutualisée.</td><td>Téléconsultation → téléexpertise → <span class=\"kw-alerte\">téléassistance (thrombolyse)</span>.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Détenus (UCSA)</span></strong></td><td>Unité de consultation et de soins ambulatoires.</td><td>Téléconsultation ; téléexpertise ; téléassistance.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">EHPAD</span></strong></td><td>Éviter les déplacements de personnes fragiles et les passages aux urgences.</td><td>Téléconsultation (<span class=\"kw-clinique\">gériatrie</span>, <span class=\"kw-clinique\">psychiatrie</span>) ; téléexpertise.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">HAD</span></strong></td><td>Hospitalisation à domicile.</td><td>Télésuivi des <span class=\"kw-clinique\">plaies chroniques</span> et des <span class=\"kw-clinique\">grossesses à risque</span> ; télésurveillance post-hospitalisation.</td></tr>\n  </tbody>\n</table>","frequence":0},{"id":"17-3","rang":"A","rubrique":"Définition","titre":"Connaître le cadre éthique et déontologique","contenu":"<p>Le <strong><span class=\"kw-def\">cadre éthique et déontologique</span></strong> de la télésanté s'inscrit dans le <span class=\"kw-def\">Code de la santé publique</span> et engage à la fois les <strong>professionnels de santé</strong> (acteurs) et les <strong><span class=\"kw-def\">plateformes</span></strong> de télésanté.</p>\n\n<h4 class=\"kw-def\">Responsabilités des acteurs (professionnels de santé)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Pertinence</span></strong> du recours à la télésanté, dont le professionnel est responsable.</li>\n  <li><strong><span class=\"kw-def\">Information</span></strong> du patient + recueil du <strong><span class=\"kw-def\">consentement libre et éclairé</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Authentification</span></strong> des professionnels de santé intervenant dans l'acte.</li>\n  <li><strong><span class=\"kw-def\">Identification du patient</span></strong> (<span class=\"kw-def\">identitovigilance</span>).</li>\n  <li><span class=\"kw-def\">Disponibilité des données médicales</span> nécessaires à l'acte ; respect des règles d'<span class=\"kw-def\">échange et de partage</span> des données.</li>\n  <li>Tenue du <strong><span class=\"kw-def\">dossier patient</span></strong> (± <span class=\"kw-def\">DMP</span>) et <strong><span class=\"kw-def\">traçabilité</span></strong> des actes.</li>\n  <li><span class=\"kw-def\">Formation</span> éventuelle du patient à l'utilisation du <span class=\"kw-def\">dispositif de télémédecine</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Responsabilités des plateformes de télésanté</h4>\n<ul>\n  <li>Conformité au <strong><span class=\"kw-def\">RGPD</span></strong> (Règlement général sur la protection des données).</li>\n  <li>Respect de la <strong><span class=\"kw-def\">PGSSIS</span></strong> (politique générale de sécurité des systèmes d'information en santé).</li>\n  <li>Respect des <strong><span class=\"kw-def\">référentiels de l'ANS</span></strong> (Agence du numérique en santé).</li>\n</ul>\n\n<h4 class=\"kw-def\">Bonnes pratiques de téléconsultation (HAS)</h4>\n<ul>\n  <li>Vérifier la <span class=\"kw-clinique\">capacité du patient</span> à bénéficier d'une <span class=\"kw-def\">téléconsultation</span>.</li>\n  <li>S'assurer de la possibilité de mise en place de la <strong><span class=\"kw-def\">vidéotransmission</span></strong>.</li>\n  <li>± Prévoir la présence d'une <span class=\"kw-clinique\">personne de l'entourage</span> ou d'un <span class=\"kw-clinique\">professionnel de santé accompagnant</span>.</li>\n  <li>S'assurer de la disponibilité des <span class=\"kw-def\">données médicales</span> nécessaires à l'acte.</li>\n  <li>Avant l'acte : informer le patient et recueillir son <strong><span class=\"kw-def\">consentement</span></strong>.</li>\n</ul>\n\n<div class=\"callout callout-danger\">⚠️ <strong>Éligibilité du patient — <span class=\"kw-ci\">contre-indication</span> :</strong> la prise en charge à distance <span class=\"kw-ci\">n'est pas adaptée aux situations exigeant un examen physique direct</span> par le professionnel médical. Il faut alors <span class=\"kw-alerte\">orienter le patient vers une consultation en présentiel</span> dans des délais compatibles avec son état de santé.</div>","frequence":0},{"id":"17-4","rang":"A","rubrique":"Définition","titre":"Connaître la communication à distance et les coopérations pluriprofessionnelles","contenu":"<p>La télésanté repose sur deux piliers complémentaires : la <strong><span class=\"kw-def\">communication à distance</span></strong> (avec le patient et son entourage) et l'<strong><span class=\"kw-def\">organisation pluriprofessionnelle</span></strong> (coopération entre soignants).</p>\n\n<h4 class=\"kw-def\">Savoir communiquer à distance</h4>\n<ul>\n  <li>Nécessité d'une <strong><span class=\"kw-def\">formation aux outils</span></strong> ; choix d'outils <span class=\"kw-def\">simples et fiables</span>.</li>\n  <li>Moyens mis à disposition du patient : <span class=\"kw-clinique\">interprète</span>, <span class=\"kw-clinique\">sous-titrage</span> de la téléconsultation, présence d'un <span class=\"kw-clinique\">aidant</span> ou d'auxiliaires médicaux.</li>\n  <li>Téléconsulter dans un <strong>cadre calme et adapté</strong> ; s'assurer du bon fonctionnement du matériel du patient et de sa capacité à l'utiliser.</li>\n  <li>Suite de la prise en charge organisée avec le patient et son <span class=\"kw-def\">médecin traitant</span> : transmission du <strong><span class=\"kw-def\">compte-rendu</span></strong> et des informations médicales.</li>\n</ul>\n\n<h4 class=\"kw-def\">Avec les usagers et les aidants</h4>\n<ul>\n  <li>S'assurer de la <span class=\"kw-clinique\">disponibilité de l'aidant</span> et l'informer du déroulement de la téléconsultation.</li>\n  <li>Recueillir le <strong><span class=\"kw-def\">consentement du patient</span></strong> à la présence de l'aidant ou de l'auxiliaire de santé.</li>\n  <li>Respect du <strong><span class=\"kw-def\">secret médical</span></strong>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Organisation : gestion du temps de travail</h4>\n<ul>\n  <li><strong>Plage horaire dédiée</strong> aux soins à distance.</li>\n  <li>Télémédecine <strong><span class=\"kw-chiffre\">&lt; 20 %</span></strong> de l'activité médicale globale effectuée à distance (avenant 9).</li>\n  <li>Anticiper la <span class=\"kw-def\">préparation</span> des actes en amont et un temps de <span class=\"kw-def\">conclusion</span> en aval.</li>\n  <li>Nécessité de <strong><span class=\"kw-def\">formation continue</span></strong> des professionnels.</li>\n</ul>\n\n<h4 class=\"kw-def\">Coopération interprofessionnelle</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Coordination et coopération</span></strong> entre professionnels : cohérence et pertinence des parcours de prise en charge.</li>\n  <li>Différents schémas : <span class=\"kw-def\">ville-hôpital</span>, <span class=\"kw-def\">médicaux–auxiliaires médicaux</span>, <span class=\"kw-def\">généraliste–spécialiste</span>.</li>\n  <li>Prérequis : <strong><span class=\"kw-def\">interopérabilité</span></strong> des outils, <span class=\"kw-def\">partage sécurisé</span> des informations, <span class=\"kw-def\">accessibilité des données</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Échange et partage de données de santé</h4>\n<ul>\n  <li>Flux de données vers un <span class=\"kw-def\">destinataire identifié</span> ; mise à disposition des données utiles à la coordination et à la continuité des soins.</li>\n  <li>Conditions : respect du <strong><span class=\"kw-def\">secret professionnel</span></strong> ; uniquement entre professionnels participant à la prise en charge d'une <strong>même personne</strong>.</li>\n  <li>Finalité de <span class=\"kw-def\">coordination</span>, de <span class=\"kw-def\">continuité des soins</span> ou de <span class=\"kw-def\">suivi médico-social</span>.</li>\n  <li><span class=\"kw-def\">Information du patient</span>, qui <span class=\"kw-alerte\">peut s'y opposer</span>.</li>\n</ul>","frequence":0},{"id":"17-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître la mise en œuvre d’un projet de télémédecine","contenu":"<p>La mise en œuvre d'un <strong><span class=\"kw-def\">projet de télémédecine</span></strong> se structure en <strong><span class=\"kw-chiffre\">4 phases</span></strong> successives — <span class=\"kw-def\">conception</span>, <span class=\"kw-def\">déploiement</span>, <span class=\"kw-def\">réalisation</span>, <span class=\"kw-def\">évaluation</span> — totalisant <strong><span class=\"kw-chiffre\">15 étapes</span></strong>.</p>\n\n<h4 class=\"kw-def\">Phase 1 — Conception du projet (8 étapes)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Identification du besoin médical</span></strong>.</li>\n  <li>Description détaillée du <span class=\"kw-def\">projet médical</span> (et du projet de soins).</li>\n  <li><strong><span class=\"kw-def\">Portage</span></strong> du projet de télémédecine.</li>\n  <li><strong><span class=\"kw-def\">Cahier des charges métier</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Cahier des charges technico-fonctionnel</span></strong>.</li>\n  <li><span class=\"kw-def\">Conservation des données de santé</span>.</li>\n  <li><span class=\"kw-def\">Responsabilité professionnelle</span> liée à l'activité de télémédecine.</li>\n  <li><span class=\"kw-def\">Formation</span> et <span class=\"kw-def\">mutualisation</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Phase 2 — Déploiement (3 étapes)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Calendrier de déploiement</span></strong>.</li>\n  <li><strong><span class=\"kw-def\">Gestion des risques a priori</span></strong> et mesures préventives.</li>\n  <li><strong><span class=\"kw-def\">Coordination</span></strong> (animation) de l'action de télémédecine.</li>\n</ul>\n\n<h4 class=\"kw-def\">Phase 3 — Réalisation / mise en production (3 étapes)</h4>\n<ul>\n  <li>Organisation de la télémédecine dans la <span class=\"kw-def\">structure</span>.</li>\n  <li><strong><span class=\"kw-alerte\">Procédures en cas de survenue de pannes techniques</span></strong>.</li>\n  <li>Organisation d'une <span class=\"kw-def\">session de télémédecine</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Phase 4 — Retours d'expérience et évaluation (1 étape)</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Retours d'expérience</span></strong> et <strong><span class=\"kw-def\">évaluation</span></strong> du projet.</li>\n</ul>\n\n<div class=\"callout callout-info\">📌 <strong>À retenir :</strong> <span class=\"kw-chiffre\">4 phases</span> — <span class=\"kw-def\">conception</span> (<span class=\"kw-chiffre\">8 étapes</span>) → <span class=\"kw-def\">déploiement</span> (<span class=\"kw-chiffre\">3 étapes</span>) → <span class=\"kw-def\">réalisation</span> (<span class=\"kw-chiffre\">3 étapes</span>) → <span class=\"kw-def\">évaluation</span> (<span class=\"kw-chiffre\">1 étape</span>).</div>","frequence":1},{"id":"17-6","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les méthodes d’évaluation","contenu":"<p>L'<strong><span class=\"kw-def\">évaluation d'un programme de télémédecine</span></strong> vise à déterminer le <span class=\"kw-def\">succès ou l'échec</span> du système au regard de ses objectifs (attendus et non-attendus). Particularité importante : il n'existe <strong><span class=\"kw-alerte\">pas de cadre d'évaluation unique</span></strong>.</p>\n\n<h4 class=\"kw-def\">Objectifs et principes de l'évaluation</h4>\n<ul>\n  <li><strong><span class=\"kw-def\">Évaluation continue</span></strong> des différentes étapes du <span class=\"kw-def\">cycle de vie</span> du service.</li>\n  <li>Évaluation à la fois <span class=\"kw-def\">technologique</span>, <span class=\"kw-def\">médicale</span> et <span class=\"kw-def\">économique</span>.</li>\n  <li>Rechercher des méthodes <strong>alternatives, plus efficaces et moins coûteuses</strong> pour atteindre les objectifs.</li>\n  <li>Rechercher les <strong><span class=\"kw-alerte\">effets indésirables / involontaires</span></strong> du programme.</li>\n  <li>Décider de la suite à donner : <span class=\"kw-def\">continuation</span>, <span class=\"kw-def\">changements</span> ou <span class=\"kw-def\">arrêt</span>.</li>\n</ul>\n\n<h4 class=\"kw-def\">Les 9 dimensions explorées</h4>\n<table >\n  <thead><tr><th>Dimension</th><th>Critères évalués</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-def\">Clinique</span></strong></td><td>Qualité et continuité des soins ; <span class=\"kw-clinique\">fiabilité diagnostique</span> ; qualité de vie ; <span class=\"kw-bio\">mesures biométriques</span>.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Perception</span></strong></td><td>Acceptabilité de la technologie ; changements pour les soignants ; culture du soin ; effets sur le taux de consultation.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Organisationnelle</span></strong></td><td>Distribution des tâches ; communication professionnels–patients ; nouveaux processus opérationnels.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Éducationnelle</span></strong></td><td>Qualité de la formation ; impact sur le recrutement et la rétention des professionnels.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Administrative</span></strong></td><td>Amélioration de l'accès aux soins ; <span class=\"kw-def\">coût-efficacité</span> ; redistribution des ressources humaines et financières.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Économique</span></strong></td><td>Viabilité économique des solutions ; création d'activités.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Technique</span></strong></td><td>Fiabilité d'usage et des technologies ; qualité du son et de la vidéo.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Sociale</span></strong></td><td>Questions éthiques ; différences géographiques et culturelles d'acceptation.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Déontologique</span></strong></td><td>Respect des droits et devoirs des parties prenantes ; clarté et fiabilité des contrats ; recours.</td></tr>\n  </tbody>\n</table>\n\n<div class=\"callout callout-warn\">⚠️ <strong>Point clé :</strong> <span class=\"kw-chiffre\">9 dimensions</span> à explorer — <span class=\"kw-def\">clinique</span>, <span class=\"kw-def\">perception</span>, <span class=\"kw-def\">organisationnelle</span>, <span class=\"kw-def\">éducationnelle</span>, <span class=\"kw-def\">administrative</span>, <span class=\"kw-def\">économique</span>, <span class=\"kw-def\">technique</span>, <span class=\"kw-def\">sociale</span>, <span class=\"kw-def\">déontologique</span>. Aucun <span class=\"kw-alerte\">cadre d'évaluation unique</span>.</div>","frequence":1}],"astuces":[],"strategie":{},"cards":[{"i":"23d95645789e","n":17,"o":"17-1","u":"Définition","t":"Connaître la définition de la télésanté, de la santé digitale et des services supports de santé numérique","q":"Comment la télésanté se décompose-t-elle selon le Code de la santé publique ?","a":"<p>La télésanté se décompose en deux versants : la <strong>télémédecine</strong> et le <strong>télésoin</strong>. Ces deux volets sont définis par la loi HPST de 2009.</p>"},{"i":"25eee57f6c16","n":17,"o":"17-1","u":"Définition","t":"Connaître la définition de la télésanté, de la santé digitale et des services supports de santé numérique","q":"Qui sont les professionnels de santé concernés par la télémédecine et le télésoin ?","a":"<ul><li>La <strong>télémédecine</strong> est réservée aux professionnels médicaux : <strong>médecin, sage-femme, chirurgien-dentiste</strong>.</li><li>Le <strong>télésoin</strong> est réservé aux professionnels non médicaux : <strong>pharmacien, auxiliaires médicaux</strong> (infirmier, kinésithérapeute).</li></ul>"},{"i":"6242fdfdd9a9","n":17,"o":"17-1","u":"Définition","t":"Connaître la définition de la télésanté, de la santé digitale et des services supports de santé numérique","q":"Quels sont les objectifs de la télémédecine d'après sa définition ?","a":"<p>La télémédecine permet, à distance et grâce aux TIC, d'<strong>établir un diagnostic</strong>, d'<strong>assurer un suivi</strong> (préventif ou post-thérapeutique), de <strong>requérir un avis spécialisé</strong>, de <strong>préparer une décision thérapeutique</strong>, de <strong>prescrire</strong> ou de <strong>surveiller l'état du patient</strong>.</p>"},{"i":"74d89b4b55c1","n":17,"o":"17-1","u":"Définition","t":"Connaître la définition de la télésanté, de la santé digitale et des services supports de santé numérique","q":"Quelle est la définition générale de la télésanté ?","a":"<p>La télésanté est le concept générique qui englobe l'ensemble des activités de santé réalisées à distance grâce aux <strong>technologies de l'information et de la communication (TIC)</strong>.</p>"},{"i":"eff6c25e6467","n":17,"o":"17-1","u":"Définition","t":"Connaître la définition de la télésanté, de la santé digitale et des services supports de santé numérique","q":"Qu'est-ce que la santé digitale et quels sont ses services socles supports ?","a":"<p>La <strong>santé digitale</strong> (ou numérique en santé) regroupe les services socles qui supportent la télésanté. Ces services incluent :</p><ul><li><strong>MSSanté</strong> : messagerie sécurisée de santé.</li><li><strong>DMP</strong> : dossier médical partagé.</li><li><strong>Agenda</strong> : centralisation des rendez-vous.</li><li><strong>E-prescription</strong> : dématérialisation des ordonnances.</li><li>Outils de coordination du parcours de santé.</li></ul>"},{"i":"11508623788c","n":17,"o":"17-2","u":"Définition","t":"Connaître l’intérêt de la télésanté dans les pratiques professionnelles","q":"De quelle manière la télésanté renforce-t-elle la qualité des soins ?","a":"<p>La télésanté renforce la qualité des soins en permettant un <strong>accès à un avis spécialisé à distance</strong> via la <strong>téléexpertise</strong>. Elle offre également la possibilité d'obtenir un <strong>second avis spécialisé</strong>.</p>"},{"i":"5be395a2e17d","n":17,"o":"17-2","u":"Définition","t":"Connaître l’intérêt de la télésanté dans les pratiques professionnelles","q":"Quels sont les trois objectifs majeurs de la télésanté dans les pratiques professionnelles, selon le référentiel ?","a":"<p>Les trois objectifs majeurs de la télésanté sont :</p><ul><li>Réduire les <strong>inégalités d'accès aux soins</strong>.</li><li>Renforcer la <strong>qualité des soins</strong>.</li><li>Améliorer la <strong>continuité des soins</strong>.</li></ul>"},{"i":"786ffc7c5892","n":17,"o":"17-2","u":"Définition","t":"Connaître l’intérêt de la télésanté dans les pratiques professionnelles","q":"Comment la télésanté contribue-t-elle à réduire les inégalités d'accès aux soins ?","a":"<p>La télésanté réduit les inégalités d'accès aux soins par :</p><ul><li>Son déploiement dans les <strong>territoires à faible densité médicale</strong> (zones sous-dotées, déserts médicaux).</li><li>La <strong>téléconsultation assistée</strong> qui renforce le maillage territorial (pharmacie, infirmier).</li><li>Des exceptions au parcours de soins autorisées en cas d'<strong>absence de médecin traitant</strong> et de <strong>faible densité médicale</strong>, s'inscrivant dans le cadre de la loi du 4 mars 2002 relative aux droits des malades.</p></li></ul>"},{"i":"b258052f9305","n":17,"o":"17-2","u":"Définition","t":"Connaître l’intérêt de la télésanté dans les pratiques professionnelles","q":"Donnez deux exemples concrets de télésanté appliqués à des domaines spécifiques mentionnés dans le référentiel.","a":"<p>Voici deux exemples :</p><ul><li>La <strong>téléradiologie</strong> : elle permet la <strong>télétransmission d'images</strong> et leur <strong>téléinterprétation</strong> par un radiologue à distance, facilitant ainsi le télédiagnostic et la téléexpertise.</li><li>La prise en charge de l'<strong>AVC</strong> : la télésanté assure la <strong>connexion entre les urgences périphériques et les UNV</strong> (Unités Neuro-Vasculaires), une garde de neurologie mutualisée, et le recours à la <strong>téléconsultation, téléexpertise et téléassistance</strong> pour la <strong>thrombolyse</strong>.</p></li></ul>"},{"i":"e39cd9f14187","n":17,"o":"17-2","u":"Définition","t":"Connaître l’intérêt de la télésanté dans les pratiques professionnelles","q":"Comment la télésanté améliore-t-elle la continuité des soins, notamment pour les pathologies chroniques ?","a":"<p>Elle améliore la continuité des soins par :</p><ul><li>Le <strong>suivi à distance des pathologies chroniques</strong>, notamment via la <strong>télésurveillance</strong> pour des affections comme l'<strong>insuffisance cardiaque</strong>, le <strong>diabète</strong>, l'<strong>insuffisance rénale chronique</strong> et l'<strong>HTA</strong>.</li><li>Le <strong>suivi post-hospitalisation</strong>, assurant une meilleure coordination ville-hôpital.</p></li></ul>"},{"i":"0605ccecb8b4","n":17,"o":"17-3","u":"Définition","t":"Connaître le cadre éthique et déontologique","q":"Quelles sont les responsabilités spécifiques des plateformes de télésanté au regard des données et de la sécurité informatique ?","a":"<ul><li>Assurer la <strong>conformité au RGPD</strong> (Règlement Général sur la Protection des Données).</li><li>Respecter la <strong>PGSSIS</strong> (politique générale de sécurité des systèmes d'information en santé).</li><li>Se conformer aux <strong>référentiels de l'ANS</strong> (Agence du Numérique en Santé).</li></ul>"},{"i":"41668f81ef82","n":17,"o":"17-3","u":"Définition","t":"Connaître le cadre éthique et déontologique","q":"Quel cadre réglementaire principal encadre l'éthique et la déontologie de la télésanté en France ?","a":"<p>Le cadre éthique et déontologique de la télésanté est principalement défini par le <strong>Code de la santé publique</strong>.</p>"},{"i":"cf813a32be13","n":17,"o":"17-3","u":"Définition","t":"Connaître le cadre éthique et déontologique","q":"Quels sont les principes des bonnes pratiques pour une téléconsultation, notamment concernant l'éligibilité du patient ?","a":"<ul><li>Vérifier la <strong>capacité du patient</strong> à bénéficier d'une téléconsultation.</li><li>S'assurer de la possibilité de mise en place de la <strong>vidéotransmission</strong>.</li><li>Informer le patient et recueillir son <strong>consentement</strong> avant l'acte.</li><li>S'assurer de la disponibilité des <strong>données médicales nécessaires</strong>.</li><li>Garantir l'<strong>éligibilité du patient</strong> : la télésanté est contre-indiquée si un <strong>examen physique direct</strong> est indispensable. Dans ce cas, le patient doit être orienté vers une consultation en présentiel.</li></ul>"},{"i":"e4d99eb279d7","n":17,"o":"17-3","u":"Définition","t":"Connaître le cadre éthique et déontologique","q":"Quelles sont les responsabilités éthiques et déontologiques d'un professionnel de santé recourant à la télésanté ?","a":"<ul><li>Vérifier la <strong>pertinence</strong> du recours à la télésanté.</li><li>Informer le patient et recueillir son <strong>consentement libre et éclairé</strong>.</li><li>Procéder à son <strong>authentification</strong> en tant que professionnel.</li><li>Assurer l'<strong>identification du patient</strong> (identitovigilance).</li><li>Garantir la disponibilité et le respect des règles d'échange des <strong>données médicales</strong>.</li><li>Assurer la <strong>tenue du dossier patient</strong> (notamment le DMP) et la traçabilité des actes.</li><li>Éventuellement, former le patient à l'utilisation du dispositif de télémédecine.</li></ul>"},{"i":"373f807b0829","n":17,"o":"17-4","u":"Définition","t":"Connaître la communication à distance et les coopérations pluriprofessionnelles","q":"Quelles sont les conditions essentielles au partage de données de santé dans le cadre de la coopération interprofessionnelle ?","a":"<p>Le partage de données de santé doit respecter les conditions suivantes :</p><ul><li>Respect du <strong>secret professionnel</strong>.</li><li>Exclusivement entre <strong>professionnels participant à la prise en charge</strong> d'une même personne.</li><li>Avoir une finalité de <strong>coordination</strong>, de <strong>continuité des soins</strong> ou de <strong>suivi médico-social</strong>.</li><li>Information du patient, qui peut s'y <strong>opposer</strong>.</li></ul>"},{"i":"37412c0fcfd1","n":17,"o":"17-4","u":"Définition","t":"Connaître la communication à distance et les coopérations pluriprofessionnelles","q":"Quels sont les moyens à mettre en œuvre pour assurer une communication à distance efficace et inclusive avec le patient lors d'une téléconsultation ?","a":"<p>Pour assurer une communication à distance efficace et inclusive, il est nécessaire de prévoir :</p><ul><li>La mise à disposition d'un <strong>interprète</strong> ou d'un <strong>sous-titrage</strong> de la téléconsultation.</li><li>La possibilité de la présence d'un <strong>aidant</strong> ou d'<strong>auxiliaires médicaux</strong>, après recueil du consentement du patient.</li><li>S'assurer du <strong>bon fonctionnement du matériel du patient</strong> et de sa capacité à l'utiliser.</li><li>Téléconsulter dans un <strong>cadre calme et adapté</strong>.</li></ul>"},{"i":"fdff9bd5a55e","n":17,"o":"17-4","u":"Définition","t":"Connaître la communication à distance et les coopérations pluriprofessionnelles","q":"Quels sont les deux piliers complémentaires sur lesquels repose la télésanté ?","a":"<p>La télésanté repose sur deux piliers complémentaires :</p><ul><li>La <strong>communication à distance</strong> (avec le patient et son entourage).</li><li>L'<strong>organisation pluriprofessionnelle</strong> (coopération entre soignants).</li></ul>"},{"i":"244ad4ae27db","n":17,"o":"17-5","u":"Prise en charge","t":"Connaître la mise en œuvre d’un projet de télémédecine","q":"Quelle est l'étape terminale d'un projet de télémédecine ?","a":"<p>L'étape terminale d'un projet de télémédecine est consacrée aux <strong>retours d'expérience et à l'évaluation du projet</strong>, afin d'en mesurer l'impact et d'identifier les axes d'amélioration.</p>"},{"i":"282f70d11715","n":17,"o":"17-5","u":"Prise en charge","t":"Connaître la mise en œuvre d’un projet de télémédecine","q":"Quelles sont les étapes clés de la phase de conception d'un projet de télémédecine ?","a":"<p>La phase de conception d'un projet de télémédecine comprend les étapes clés suivantes :</p><ul><li>Identification du <strong>besoin médical</strong>.</li><li>Description détaillée du <strong>projet médical</strong> et du projet de soins.</li><li><strong>Portage du projet</strong> de télémédecine.</li><li>Rédaction du <strong>cahier des charges métier</strong>.</li><li>Rédaction du <strong>cahier des charges technico-fonctionnel</strong>.</li><li>Définition des modalités de <strong>conservation des données de santé</strong>.</li><li>Précision de la <strong>responsabilité professionnelle</strong> liée à l'activité de télémédecine.</li><li>Mise en place de la <strong>formation</strong> et de la mutualisation.</li></ul>"},{"i":"35fe028576a0","n":17,"o":"17-5","u":"Prise en charge","t":"Connaître la mise en œuvre d’un projet de télémédecine","q":"Quelles sont les étapes de la phase de déploiement d'un projet de télémédecine ?","a":"<p>Les étapes de la phase de déploiement d'un projet de télémédecine sont :</p><ul><li>L'établissement du <strong>calendrier de déploiement</strong>.</li><li>La gestion des <strong>risques a priori</strong> et des mesures préventives associées.</li><li>La <strong>coordination</strong> (animation) de l'action de télémédecine.</li></ul>"},{"i":"3f06c229f7f3","n":17,"o":"17-5","u":"Prise en charge","t":"Connaître la mise en œuvre d’un projet de télémédecine","q":"Quelles sont les quatre grandes phases de mise en œuvre d'un projet de télémédecine, selon les recommandations françaises ?","a":"<p>Les quatre phases successives de mise en œuvre d'un projet de télémédecine sont :</p><ul><li>La phase de <strong>conception</strong>.</li><li>La phase de <strong>déploiement</strong>.</li><li>La phase de <strong>réalisation</strong> (ou mise en production).</li><li>La phase d'<strong>évaluation</strong> (ou retours d'expérience).</li></ul>"},{"i":"6c815b62a8e3","n":17,"o":"17-5","u":"Prise en charge","t":"Connaître la mise en œuvre d’un projet de télémédecine","q":"Quelles sont les étapes de la phase de réalisation (ou mise en production) d'un projet de télémédecine ?","a":"<p>La phase de réalisation ou mise en production d'un projet de télémédecine inclut les étapes suivantes :</p><ul><li>L'<strong>organisation de la télémédecine</strong> au sein de la structure.</li><li>La définition des <strong>procédures en cas de pannes techniques</strong>.</li><li>L'<strong>organisation d'une session de télémédecine</strong>.</li></ul>"}]};